void Solver::bump_var(int var, double coeff) {
    // Validate variable index
    if (var < 1 || var > vars) return;

    // Increase activity with the given coefficient
    activity[var] += var_inc * coeff;

    // Rescale activities and increment if values become too large
    const double ACT_LIMIT = 1e150;
    if (activity[var] > ACT_LIMIT) {
        const double SCALE = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        // Insert the variable if it is not already in the heap
        vsids.insert(var);
    }
}

